#!/usr/bin/env python3
"""symbols.yml / emoji.yml (Kashiko IME) から SymbolData.swift / EmojiShortcodeData.swift を生成する。

Usage: python3 Tools/generate_symbol_data.py <symbols.yml> <emoji.yml>
Requires PyYAML.
"""
import sys
from pathlib import Path

import yaml

OUT_DIR = Path(__file__).resolve().parent.parent / "Sources/KanaKanjiConverterModule/ConverterAPI/SpecialConversion"

LICENSE = """\
// This file is derived from data of Mozc (https://github.com/google/mozc):
// symbol.tsv (symbols) and emoji_data.tsv (emoji), and Unicode emoji-test.txt (shortcodes).
// Generated by Tools/generate_symbol_data.py. Do not edit.
//
// Copyright 2010-2018, Google Inc.
// All rights reserved.
//
// Redistribution and use in source and binary forms, with or without
// modification, are permitted provided that the following conditions are
// met:
//
//     * Redistributions of source code must retain the above copyright
// notice, this list of conditions and the following disclaimer.
//     * Redistributions in binary form must reproduce the above
// copyright notice, this list of conditions and the following disclaimer
// in the documentation and/or other materials provided with the
// distribution.
//     * Neither the name of Google Inc. nor the names of its
// contributors may be used to endorse or promote products derived from
// this software without specific prior written permission.
//
// THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS
// "AS IS" AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT
// LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR
// A PARTICULAR PURPOSE ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT
// OWNER OR CONTRIBUTORS BE LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL,
// SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT
// LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR SERVICES; LOSS OF USE,
// DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER CAUSED AND ON ANY
// THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT
// (INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE
// OF THIS SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.
"""


class Loader(yaml.SafeLoader):
    pass


# `<<` や `=` を記号として読むため、merge / value の暗黙タグを外す
Loader.yaml_implicit_resolvers = {
    k: [r for r in v if r[0] not in ("tag:yaml.org,2002:merge", "tag:yaml.org,2002:value")]
    for k, v in yaml.SafeLoader.yaml_implicit_resolvers.items()
}


def is_hiragana(s):
    return bool(s) and all("ぁ" <= c <= "ゟ" or c == "ー" for c in s)


def check(*fields):
    for f in fields:
        assert not any(c in "\t\n\r" for c in f), repr(f)
        assert '"""' not in f and "\\#" not in f, repr(f)


def write(name, enum_name, sections):
    body = [LICENSE, "\nenum %s {" % enum_name]
    for prop, lines in sections:
        body.append('    static let %s = #"""\n%s\n"""#' % (prop, "\n".join(lines)))
    body.append("}\n")
    (OUT_DIR / name).write_text("\n".join(body), encoding="utf-8")


def main(symbols_path, emoji_path):
    symbols = yaml.load(open(symbols_path, encoding="utf-8"), Loader)
    readings = {}
    for entry in symbols["entries"]:
        for reading in map(str, entry["readings"]):
            if is_hiragana(reading):
                bucket = readings.setdefault(reading, [])
                if entry["char"] not in bucket:
                    bucket.append(entry["char"])
    reading_lines, variant_lines = [], []
    for reading, chars in readings.items():
        check(reading, *chars)
        reading_lines.append("\t".join([reading, *chars]))
    for v in symbols["variants"]:
        chain = [str(c) for c in v["chain"] if str(c) != str(v["key"])]
        check(str(v["key"]), *chain)
        variant_lines.append("\t".join([str(v["key"]), *chain]))
    write("SymbolData.swift", "SymbolData", [("readings", reading_lines), ("variants", variant_lines)])

    emoji = yaml.load(open(emoji_path, encoding="utf-8"), Loader)
    lines = []
    for entry in emoji["entries"]:
        triggers = []
        for t in map(str, entry.get("triggers", [])):
            if t.isascii() and " " not in t and t not in triggers:
                triggers.append(t)
        if not triggers:
            continue
        check(entry["char"], *triggers)
        lines.append(entry["char"] + "\t" + " ".join(triggers))
    write("EmojiShortcodeData.swift", "EmojiShortcodeData", [("entries", lines)])


if __name__ == "__main__":
    main(*sys.argv[1:3])
